#!/usr/bin/python3
"""Offline LAS2-S stereo candidate. Outputs are estimates, never navigation data."""
import argparse,hashlib,json,resource,sys,time
from pathlib import Path
import cv2,numpy as np,torch
p=argparse.ArgumentParser();p.add_argument('inputs');p.add_argument('output');p.add_argument('--threads',type=int,default=4);a=p.parse_args();root=Path('/work/cartographer/v5');sys.path.insert(0,str(root/'upstream/LiteAnyStereo'));from core.models import build_model,load_model_weights
from core.utils.utils import InputPadder
torch.set_num_threads(a.threads);cv2.setNumThreads(1);checkpoint=root/'models/LAS2_S.pth';model=build_model('las2',model_size='s',fnet_pretrained=False,max_disp=192);load_model_weights(model,torch.load(checkpoint,map_location='cpu',weights_only=True),strict=True);model.eval();out=Path(a.output);out.mkdir(parents=True,exist_ok=True);rows=[]
def disparity(left,right):
 l=torch.from_numpy(np.ascontiguousarray(left)).float()[None,None].repeat(1,3,1,1);r=torch.from_numpy(np.ascontiguousarray(right)).float()[None,None].repeat(1,3,1,1);padder=InputPadder(l.shape,divis_by=32);l,r=padder.pad(l,r)
 with torch.inference_mode():d=padder.unpad(model(l,r,max_disp=192,test_mode=True)).float().numpy().reshape(left.shape)
 return d
for f in sorted(Path(a.inputs).glob('frame-*.npz')):
 sample=np.load(f);left=sample['left'];right=sample['right'];K=sample['K'];b=float(sample['baseline']);size=(left.shape[1]//2,left.shape[0]//2);l=cv2.resize(left,size,interpolation=cv2.INTER_AREA);r=cv2.resize(right,size,interpolation=cv2.INTER_AREA);start=time.perf_counter();d=disparity(l,r);dr=disparity(r[:,::-1],l[:,::-1])[:,::-1];elapsed=time.perf_counter()-start;y,x=np.indices(d.shape,dtype=np.float32);xr=x-d;rd=cv2.remap(dr,xr,y,cv2.INTER_LINEAR,borderMode=cv2.BORDER_CONSTANT,borderValue=-1);lr=np.abs(d-rd);warp=cv2.remap(r,xr,y,cv2.INTER_LINEAR);photo=cv2.boxFilter(np.abs(l.astype(np.float32)-warp.astype(np.float32)),cv2.CV_32F,(5,5));mask=cv2.resize(sample['self_mask'].astype(np.uint8),size,interpolation=cv2.INTER_AREA)>0;valid=np.isfinite(d)&(d>0)&(xr>=0)&(xr<size[0]-1)&(rd>0)&(lr<.375)&(photo<20.)&~mask;depth=(K[0]*.5*b)/np.maximum(d,1e-6);valid&=(depth>.25)&(depth<8);filtered=np.where(valid,depth,np.nan).astype(np.float32);native=cv2.resize(filtered,(left.shape[1],left.shape[0]),interpolation=cv2.INTER_NEAREST);raw=cv2.resize(depth,(left.shape[1],left.shape[0]),interpolation=cv2.INTER_NEAREST);np.savez_compressed(out/f.name,stamp=sample['stamp'],inferred_depth=native,raw_inferred_depth=raw,lr_error=lr,photometric_error=photo)
 rows.append({'frame':f.name,'stereo_pair_inference_and_validation_s':elapsed,'filtered_fraction':float(valid.mean()),'maximum_rss_MiB':resource.getrusage(resource.RUSAGE_SELF).ru_maxrss/1024});print(json.dumps(rows[-1]),flush=True)
report={'model':'LAS2-S','source_commit':'8c97bd4c4da3712c2ac60003a23201dfdb5935f4','checkpoint_sha256':hashlib.sha256(checkpoint.read_bytes()).hexdigest(),'input':'Actual recorded monochrome stereo, replicated channels; calibration-specific metric scale','device':'development CPU, not Jetson timing','threads':a.threads,'prediction_is_navigation_input':False,'validation':'Independent mesh evaluation required before flight consideration; LR/photo consistency alone is insufficient on blank surfaces','frames':rows};(out/'benchmark.json').write_text(json.dumps(report,indent=2))
